INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(46011, 'Joshua 1:15', 'Joshua', 1, 15, 'ترڅو هغوی هغه ځمکه ونیسي چې د اردن د سیند په لوېدیځه خوا کې پرته ده او څښتن هغوی ته ورکړې ده. کله چې هغه د اسراییلو ټولو قبیلو ته ارامي راوستله، نو بیا تاسو کولای شئ چې بېرته راشئ او په خپله خاوره کې واوسېږئ چې د اردن د سیند په ختیځه خوا کې پرته ده او موسی تاسو ته درکړې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_15.mp3', '', 1761754199, 1761754199),
(46012, 'Joshua 1:16', 'Joshua', 1, 16, 'هغوی یوشع ته په ځواب کې وویل: «څه چې تا مونږ ته ویلي دي هغه ټول به سرته ورسوو او هر چېرته چې مونږ لېږې، هلته به ځو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_16.mp3', '', 1761754199, 1761754199),
(46013, 'Joshua 1:17', 'Joshua', 1, 17, 'لکه څنګه چې مونږ تل د موسی اطاعت کاوه، هماغه شان به ستا اطاعت کوو. زمونږ څښتن خدای دې ستا سره مل وي لکه څنګه چې د موسی سره مل ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_17.mp3', '', 1761754199, 1761754199),
(46014, 'Joshua 1:18', 'Joshua', 1, 18, 'هرڅوک چې ستا په وړاندې سرکښي وکړي یا ستا د کوم حکم څخه سرغړونه وکړي هغه به وژل کیږي. نو قوي او زړور اوسه!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua1_verse_18.mp3', '', 1761754199, 1761754199),
(46015, 'Psalms 68:1', 'Psalms', 68, 1, 'خدای دې راپورته شي او خواره واره دې کړي خپل دښمنان تېښته دې کړي څوک چې نفرت کوي له هغه څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_1.mp3', '', 1761754199, 1761754199),
(46016, 'Psalms 68:2', 'Psalms', 68, 2, 'لکه د باد په وړاندې چې لوګی ورکیږي داسې ته ورک کړه هغوی لکه چې څنګه ویلي کیږي موم د اور په مخکې داسې بدکاره دې تباه شي د خدای په مخکې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_2.mp3', '', 1761754199, 1761754199),
(46017, 'Psalms 68:3', 'Psalms', 68, 3, 'خو نېکان دې وي خوشحاله کړي خوشحالي دې د هغه حضور کې وي دې خوشحاله او وهي دې د خوښۍ چیغې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_3.mp3', '', 1761754199, 1761754199),
(46018, 'Psalms 68:4', 'Psalms', 68, 4, 'خدای ته ووایئ سندره ثنا صفت یې د نامه وکړئ صفت یې وکړئ چې سپریږي هغه ورېځو باندې خوشحالي وکړئ د هغه حضور کې ځکه چې یې نوم دی څښتن!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_4.mp3', '', 1761754199, 1761754199),
(46019, 'Psalms 68:5', 'Psalms', 68, 5, 'هغه خدای کوم چې اوسیږي خپل سپېڅلي ځای کې دی دا پلار د یتیمانو او ساتنه کړي د کونډو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_5.mp3', '', 1761754199, 1761754199),
(46020, 'Psalms 68:6', 'Psalms', 68, 6, 'یوځای کوي هغه بې‌کسه کورنیو سره راخلاصوي بندیان له بنده نېکمرغیو لره وچو میرو کې به اوسیږي سرکښان خلک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_6.mp3', '', 1761754199, 1761754199),
(46021, 'Psalms 68:7', 'Psalms', 68, 7, 'ای خدایه کله چې روان وې ته د خپل قوم مخکې کله چې تا وکړ مزل شوې بیابان څخه تېر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_7.mp3', '', 1761754199, 1761754199),
(46022, 'Psalms 68:8', 'Psalms', 68, 8, 'ولړزېدله ځمکه او هم له اسمانه ورېدلو باران په دې خاطر چې راروان دی د سینا خدای چې خدای د اسراییلو راروان دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_8.mp3', '', 1761754199, 1761754199),
(46023, 'Psalms 68:9', 'Psalms', 68, 9, 'تا راووراوه ډېر زیات باران او تا کړه اباده خپله شاړه ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_9.mp3', '', 1761754199, 1761754199),
(46024, 'Psalms 68:10', 'Psalms', 68, 10, 'ستا قوم کړ جوړ استوګنځی خپل هلته د نېکۍ نه دې محتاجو ته هرڅه تیار کړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_10.mp3', '', 1761754199, 1761754199),
(46025, 'Psalms 68:11', 'Psalms', 68, 11, 'څښتن ورکړلو فرمان دا زېری یووړلو د ښځو یوې غټې ډلې:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_11.mp3', '', 1761754199, 1761754199),
(46026, 'Psalms 68:12', 'Psalms', 68, 12, '«دي پاچاهان خپلو لښکرو سره تېښته کې» په کور کې پاتې ښځې وېشي د جګړې غنیمت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_12.mp3', '', 1761754199, 1761754199),
(46027, 'Psalms 68:13', 'Psalms', 68, 13, 'وې پوښل شوې په سپین زرو د کوترو څېرې په ښو سرو زرو یې وزرونه ځلېدل (ولې د ستاسو ځینې کسان د جګړې په ورځ د پسونو په شپولونو کې پاتې شول؟)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_13.mp3', '', 1761754199, 1761754199),
(46028, 'Psalms 68:14', 'Psalms', 68, 14, 'خواره واره چې کړل پاچاهان مطلق قادر خدای هلته وو لکه واوره چې وریږي د صلمون په غره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_14.mp3', '', 1761754199, 1761754199),
(46029, 'Psalms 68:15', 'Psalms', 68, 15, 'ای ځواکمن غره، د باشان غره! ای ته خاوند د ډېرو څوکو، د باشان غره!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_15.mp3', '', 1761754199, 1761754199),
(46030, 'Psalms 68:16', 'Psalms', 68, 16, 'ای د ډېرو څوکو غره! ته ولې ګورې هغه غره ته د حسد له مخې کوم چې خدای دی غوره کړی اوسېدو دپاره څښتن به اوسي هلته تل دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_16.mp3', '', 1761754199, 1761754199),
(46031, 'Psalms 68:17', 'Psalms', 68, 17, 'زرګونو زرو نظامي ځواکمنو ګاډیو سره راغی څښتن سپېڅلي ځای ته له سینا څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_17.mp3', '', 1761754199, 1761754199),
(46032, 'Psalms 68:18', 'Psalms', 68, 18, 'لوړو ځایونو ته وروختلې یووړل دې له ځانه سره زیات بندیان حتی له سرکښانو دې هم تحفې اخیستې نو څښتن خدای به هلته اوسي د هغوی په منځ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_18.mp3', '', 1761754199, 1761754199),
(46033, 'Psalms 68:19', 'Psalms', 68, 19, 'ثنا او صفت دې وي څښتن ته چې هره ورځ زمونږ بارونه وړي په خپلو اوږو دا خدای زمونږه خلاصوونکی خدای دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_19.mp3', '', 1761754199, 1761754199),
(46034, 'Psalms 68:20', 'Psalms', 68, 20, 'زمونږ خدای د خلاصون خدای دی څښتن تعالی چې له مرګي مو ژغوري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_20.mp3', '', 1761754199, 1761754199),
(46035, 'Psalms 68:21', 'Psalms', 68, 21, 'وټکوي به خدای سرونه د خپلو دښمنانو دا ببر سري چې تګ کړي په ګناهکارو لارو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_21.mp3', '', 1761754199, 1761754199),
(46036, 'Psalms 68:22', 'Psalms', 68, 22, 'داسې وویل څښتن: «راولم زه به دښمنان ستاسو باشان نه بېرته دریاب د تل نه به هغوی زه راولمه بېرته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_22.mp3', '', 1761754199, 1761754199),
(46037, 'Psalms 68:23', 'Psalms', 68, 23, 'نو ډنډوکي د دوی د وینو به شي ستاسې د لغتو لاندې او ستاسې سپي به یې څټي چې څومره غواړي هغوی»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_23.mp3', '', 1761754199, 1761754199),
(46038, 'Psalms 68:24', 'Psalms', 68, 24, 'ای خدایه، ټولو خلکو ولیده ستا د کامیابۍ مارش مارش د خدای یعنې زما د پاچا چې داخل شو خپل سپېڅلي ځای ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_24.mp3', '', 1761754199, 1761754199),
(46039, 'Psalms 68:25', 'Psalms', 68, 25, 'سندرغاړي یې په مخکې، د سازونو والا شاته او په منځ کې ځوانې ښځې چې چمبې وهي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_25.mp3', '', 1761754199, 1761754199),
(46040, 'Psalms 68:26', 'Psalms', 68, 26, '«د خدای صفت وکړئ مجلس کې د هغه د ولس ای د اسراییلو اولادې ټول وکړئ صفت د څښتن»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_26.mp3', '', 1761754199, 1761754199),
(46041, 'Psalms 68:27', 'Psalms', 68, 27, 'لومړی راځي بنیامین یعنې د ټولو نه کوچنۍ قبیله بیا ورپسې به وي مشران د یهودا د خپلې ډلې سره او بیا مشران د زبولون او نفتالي ورپسې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_27.mp3', '', 1761754199, 1761754199),
(46042, 'Psalms 68:28', 'Psalms', 68, 28, 'ای خدایه ته خپل قدرت وښایه هغه قدرت چې تا زمونږ په خاطر کار ترې واخیست', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_28.mp3', '', 1761754199, 1761754199),
(46043, 'Psalms 68:29', 'Psalms', 68, 29, 'ستا د کور په خاطر پروت اورشلیم کې چې دی چېرته چې تاته پاچاهان خپل سوغاتونه راوړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_29.mp3', '', 1761754199, 1761754199),
(46044, 'Psalms 68:30', 'Psalms', 68, 30, 'ورټه مصر په مثال دی د وحشي حیوان چې لوخو کې اوسیږي هغه ورټه نور قومونه کوم چې په مثال دي د غویانو او خوسیانو پادې ترڅو چې ټول وکړي سجده تاته او درکړي تاته خپلې نقرې خواره واره کړه ته هغه قومونه چې جګړه خوښوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_30.mp3', '', 1761754199, 1761754199),
(46045, 'Psalms 68:31', 'Psalms', 68, 31, 'استازي رابه شي له مصر څخه ایتوپیایان به خدای ته پورته کړي لاسونه د دعا دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_31.mp3', '', 1761754199, 1761754199),
(46046, 'Psalms 68:32', 'Psalms', 68, 32, 'خدای ته ووایئ سندره پاچاهیو د نړۍ ټولو په سندرو کې صفت د څښتن وکړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_32.mp3', '', 1761754199, 1761754199),
(46047, 'Psalms 68:33', 'Psalms', 68, 33, 'د هغه چا دپاره چې په لرغونو اسمانونو ناست دی چې په قوي اواز غوریږي له اسمانه څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_33.mp3', '', 1761754199, 1761754199),
(46048, 'Psalms 68:34', 'Psalms', 68, 34, 'خلکو ته ووایئ چې خدای قوي دی چې جلال د هغه ځلیږي اسراییلو باندې او لیدل کیږي یې قدرت اسمان کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_34.mp3', '', 1761754199, 1761754199),
(46049, 'Psalms 68:35', 'Psalms', 68, 35, 'خپل سپېڅلي کور کې خدای دی څومره هیبتناک د اسراییلو خدای! ورکوي خپل قوم ته قدرت او طاقت ثنا او صفت دې وي خدای ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms68_verse_35.mp3', '', 1761754199, 1761754199),
(46050, 'Proverbs 2:1', 'Proverbs', 2, 1, 'ای زما زویه! که ته زما خبرې ومنې او حکمونه مې د زړه په تل کې ذخیره کړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_1.mp3', '', 1761754199, 1761754199),
(46051, 'Proverbs 2:2', 'Proverbs', 2, 2, 'نو زما د حکمت خبرو ته غوږ ونیسه او خپل زړه پوهې ته رامات کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_2.mp3', '', 1761754199, 1761754199),
(46052, 'Proverbs 2:3', 'Proverbs', 2, 3, 'که په حقیقت کې د عقل غوښتلو دپاره خپل غږ پورته کړې او د پوهې دپاره په لوړ اواز نارې ووهې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_3.mp3', '', 1761754199, 1761754199),
(46053, 'Proverbs 2:4', 'Proverbs', 2, 4, 'که د سپینو زرو په شان یې لټون وکړې او د پټو خزانو په څېر ورپسې وګرځې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_4.mp3', '', 1761754199, 1761754199),
(46054, 'Proverbs 2:5', 'Proverbs', 2, 5, 'نو په دې به پوه شې چې څنګه له څښتن څخه ووېرېږې او د خدای پېژندلو علم به حاصل کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_5.mp3', '', 1761754199, 1761754199),
(46055, 'Proverbs 2:6', 'Proverbs', 2, 6, 'ځکه دا څښتن دی چې حکمت ورکوي او د هغه له خولې نه علم او پوهه راوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_6.mp3', '', 1761754199, 1761754199),
(46056, 'Proverbs 2:7', 'Proverbs', 2, 7, 'هغه رښتینو خلکو ته د حکمت خزانې ورکوي او د هغوی دپاره سپر دی چې خپل ژوند په صداقت تېروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_7.mp3', '', 1761754199, 1761754199),
(46057, 'Proverbs 2:8', 'Proverbs', 2, 8, 'ترڅو د انصاف کوونکو د لارو حفاظت وکړي او د خپلو وفادارانو د لارې ساتنه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_8.mp3', '', 1761754199, 1761754199),
(46058, 'Proverbs 2:9', 'Proverbs', 2, 9, 'نو بیا به ته په انصاف، عدالت او برابرۍ پوه شې او ته به ټولې ګټورې لارې وپېژنې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_9.mp3', '', 1761754199, 1761754199),
(46059, 'Proverbs 2:10', 'Proverbs', 2, 10, 'نو حکمت به ستا د زړه تل ته ښکته شي علم به ستا روح خوشحاله کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_10.mp3', '', 1761754199, 1761754199),
(46060, 'Proverbs 2:11', 'Proverbs', 2, 11, 'لیاقت به تا د خپل نظر لاندې وساتي او پوهه به دې ټینګ حفاظت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_11.mp3', '', 1761754199, 1761754199),
(46061, 'Proverbs 2:12', 'Proverbs', 2, 12, 'نو بیا به حکمت تا د بدکارو خلکو نه وژغوري له هغه خلکو نه چې بدې خبرې کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_12.mp3', '', 1761754199, 1761754199),
(46062, 'Proverbs 2:13', 'Proverbs', 2, 13, 'څوک چې د صداقت لارې پرېږدي او په تورو تیارو لارو تلل کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_13.mp3', '', 1761754199, 1761754199),
(46063, 'Proverbs 2:14', 'Proverbs', 2, 14, 'څوک چې د بدو کارونو په کولو خوشحالیږي نو له کږو لارو نه خوند اخلي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_14.mp3', '', 1761754199, 1761754199),
(46064, 'Proverbs 2:15', 'Proverbs', 2, 15, 'د چا لارې چې کږې وږې دي نو ټولې چارې یې غولوونکې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_15.mp3', '', 1761754199, 1761754199),
(46065, 'Proverbs 2:16', 'Proverbs', 2, 16, 'نو حکمت به تا د بل چا له ښځې نه وژغوري د هغې ښځې نه چې غوړې خبرې کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_16.mp3', '', 1761754199, 1761754199),
(46066, 'Proverbs 2:17', 'Proverbs', 2, 17, 'چا چې د ځوانۍ د وخت مېړه پریښی او خپل لوظ یې هېر کړی چې د خدای سره کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_17.mp3', '', 1761754199, 1761754199),
(46067, 'Proverbs 2:18', 'Proverbs', 2, 18, 'ځکه د هغې د کور لار د مرګ لور ته ښکته کیږي او لارې یې د مړو دنیا په لور لاندې تللې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_18.mp3', '', 1761754199, 1761754199),
(46068, 'Proverbs 2:19', 'Proverbs', 2, 19, 'هرڅوک چې د هغې غېږ ته ورشي بیا بېرته نه راځي او هېڅکله به هغوی د ژوند لارو ته ونه رسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_19.mp3', '', 1761754199, 1761754199),
(46069, 'Proverbs 2:20', 'Proverbs', 2, 20, 'نو بیا به ته د ښو خلکو په لاره روان شې او د نېکانو په لارو کې به پاتې شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_20.mp3', '', 1761754199, 1761754199),
(46070, 'Proverbs 2:21', 'Proverbs', 2, 21, 'نو په حقیقت کې به رښتیني خلک په دې ځمکه کې واوسیږي او هغه څوک به په کې پاتې شي چې د پاکو زړونو خاوندان وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_21.mp3', '', 1761754199, 1761754199),
(46071, 'Proverbs 2:22', 'Proverbs', 2, 22, 'خو بدکاران به د ځمکې له سر نه لېرې شي او خاینان به ترې له ریښې نه وویستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs2_verse_22.mp3', '', 1761754199, 1761754199),
(46072, 'Numbers 16:3', 'Numbers', 16, 3, 'هغوی موسی او هارون ته ورغلل او ویې ویل: «تاسو ولې داسې فکر کوئ چې د نورو څخه ډېر ښه یئ؟ د قوم ټول غړي د څښتن سپېڅلي خلک دي او څښتن زمونږ ټولو سره مل دی. نو موسی بیا ولې خپل ځان د څښتن د قوم څخه لوړ ګڼې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_3.mp3', '', 1761754199, 1761754199),
(46073, 'Numbers 16:4', 'Numbers', 16, 4, 'کله چې موسی دا خبرې واورېدلې، په ځمکه باندې پړمخې پرېوت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_4.mp3', '', 1761754199, 1761754199),
(46074, 'Numbers 16:5', 'Numbers', 16, 5, 'بیا هغه قورح او د هغه پیروانو ته داسې وویل: «سبا سهار به څښتن مونږ ته راوښایي چې څوک د هغه خپل کس دی او څوک سپېڅلی دی. او هغه کس چې هغه غوره کړی دی، هغه به پرېږدي چې نژدې ورشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_5.mp3', '', 1761754199, 1761754199),
(46075, 'Numbers 16:8', 'Numbers', 16, 8, 'موسی د قورح سره خپلو خبرو ته دوام ورکړ: «ای لاویانو، واورئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_8.mp3', '', 1761754199, 1761754199),
(46076, 'Numbers 16:9', 'Numbers', 16, 9, 'تاسو فکر کوئ چې دا وړه خبره ده چې د اسراییلو خدای تاسو د خپل قوم څخه غوره کړي یئ د دې دپاره چې هغه ته ورنژدې شئ، په سپېڅلې خېمه کې خپل کار وکړئ او د قوم خدمت وکړئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_9.mp3', '', 1761754199, 1761754199),
(46077, 'Numbers 16:10', 'Numbers', 16, 10, 'څښتن تاسو ته یو ځانګړی مسوولیت در په غاړه کړی دی او اوس فکر کوئ چې تاسو به هم کاهنان شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_10.mp3', '', 1761754199, 1761754199),
(46078, 'Numbers 16:11', 'Numbers', 16, 11, 'تا او ستا پیروانو د څښتن په وړاندې سرکښي کړې ده، د هارون په وړاندې مو نه ده کړې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_11.mp3', '', 1761754199, 1761754199),
(46079, 'Numbers 16:12', 'Numbers', 16, 12, 'بیا موسی داتان او ابیرام راوغوښتل، خو هغوی بېرته دا پیغام ورولېږه: «مونږ نه راځو!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_12.mp3', '', 1761754199, 1761754199),
(46080, 'Numbers 16:13', 'Numbers', 16, 13, 'ایا دا بس نه ده چې مونږ دې د مصر د غني او حاصلخېزې ځمکې څخه راوستلو چې دلته په دښته کې مو ووژنې؟ اوس ته غواړې چې په مونږ باندې خپل ځان بادار کړې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_13.mp3', '', 1761754199, 1761754199),
(46081, 'Numbers 16:14', 'Numbers', 16, 14, 'بله دا چې تا مونږ غني او حاصلخېزې ځمکې ته رانه وستلو او نه دې مونږ ته هغه ځمکه د خپل ملکیت په توګه راکړه چې پټي او د انګورو باغونه په کې دي او اوس هڅه کوې چې مونږ وغولوې. مونږ به رانه شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_14.mp3', '', 1761754199, 1761754199),
(46082, 'Numbers 16:15', 'Numbers', 16, 15, 'موسی ډېر په قهر شو او څښتن ته یې وویل: «د هغوی نذرانې مه قبلوه! ما د هغوی سره هېڅ غلطي نه ده کړې. حتی د هغوی څخه مې یو خر هم نه دی اخیستی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_15.mp3', '', 1761754199, 1761754199),
(46083, 'Numbers 16:16', 'Numbers', 16, 16, 'بیا موسی قورح ته وویل: «سبا ته او ستا دوه سوه پنځوس تنه پیروان باید د هارون سره د څښتن حضور ته سپېڅلې خېمې ته لاړ شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_16.mp3', '', 1761754199, 1761754199),
(46084, 'Numbers 16:17', 'Numbers', 16, 17, 'تاسو هر یو د ځان سره خپل د اور لوښی چې خوشبویي په کې وي یوسئ او څښتن ته خوشبویي وړاندې کړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_17.mp3', '', 1761754199, 1761754199),
(46085, 'Numbers 16:18', 'Numbers', 16, 18, 'نو بله ورځ هغوی هر یو خپل د اور لوښی واخیست او بل شوي سکاره او خوشبویي یې په کې واچول او د موسی او هارون سره د سپېڅلې خېمې د دروازې په خوله کې ودرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_18.mp3', '', 1761754199, 1761754199),
(46086, 'Numbers 16:19', 'Numbers', 16, 19, 'بیا قورح ټول قوم راټول کړ او هغوی موسی او هارون ته مخامخ د سپېڅلې خېمې د دروازې په خوله کې ودرېدل. ناڅاپه د څښتن جلال ټول قوم ته ښکاره شو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_19.mp3', '', 1761754199, 1761754199),
(46087, 'Numbers 16:20', 'Numbers', 16, 20, 'او څښتن موسی او هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_20.mp3', '', 1761754199, 1761754199),
(46088, 'Numbers 16:21', 'Numbers', 16, 21, '«د دې خلکو څخه لېرې شئ، زه به همدا اوس هغوی ووژنم!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_21.mp3', '', 1761754199, 1761754199),
(46089, 'Numbers 16:22', 'Numbers', 16, 22, 'خو موسی او هارون پړمخې پرېوتل او داسې دعا یې وکړه: «زمونږ خدایه، تا دغو خلکو ته ژوند ورکړ. ولې د یو سړي د ګناه په خاطر ټول قوم ته سزا ورکوې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_22.mp3', '', 1761754199, 1761754199),
(46090, 'Numbers 16:23', 'Numbers', 16, 23, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_23.mp3', '', 1761754199, 1761754199),
(46091, 'Numbers 16:24', 'Numbers', 16, 24, '«خلکو ته ووایه چې د قورح، داتان او ابیرام د خېمو څخه لېرې شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_24.mp3', '', 1761754199, 1761754199),
(46092, 'Numbers 16:25', 'Numbers', 16, 25, 'موسی داتان او ابیرام ته ورغی او د اسراییلو نور مشران ورپسې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_25.mp3', '', 1761754199, 1761754199),
(46093, 'Numbers 16:26', 'Numbers', 16, 26, 'بیا موسی قوم ته داسې خبرداری ورکړ: «د دغو بدکارو خلکو د خېمو څخه لېرې شئ! د هغوی شیانو ته لاس مه وروړئ. که نه، نو د هغوی د ګناهونو له امله به تاسو هم له منځه لاړ شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_26.mp3', '', 1761754199, 1761754199),
(46094, 'Numbers 16:27', 'Numbers', 16, 27, 'نو هغوی د قورح، داتان او ابیرام د خېمو څخه لېرې شول. داتان او ابیرام راوتلي وو او د خپلو ښځو او ماشومانو سره د خپلو خېمو په دروازو کې ولاړ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_27.mp3', '', 1761754199, 1761754199),
(46095, 'Numbers 16:28', 'Numbers', 16, 28, 'موسی قوم ته وویل: «تاسو به په دې پوه شئ چې څښتن زه رالېږلی یم چې دا ټول کارونه وکړم، دا کارونه مې په خپله خوښه نه دي کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_28.mp3', '', 1761754199, 1761754199),
(46096, 'Numbers 16:29', 'Numbers', 16, 29, 'که چېرې دا خلک د خدای د سزا څخه پرته په خپل مرګ مړه شي، د دې معنی به دا وي چې څښتن زه نه یم رالېږلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_29.mp3', '', 1761754199, 1761754199),
(46097, 'Numbers 16:30', 'Numbers', 16, 30, 'خو فرض کړئ څښتن داسې کار وکړي چې پخوا هېڅکله نه وي شوی. که چېرې ځمکه پرانیستل شي او هغوی د خپلو ټولو شیانو سره ژوندي تېر کړي، ترڅو هغوی ژوندي په ځمکه کې ښخ شي، بیا به تاسو پوه شئ چې هغوی د څښتن څخه مخ اړولی دی!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_30.mp3', '', 1761754199, 1761754199),
(46098, 'Numbers 16:31', 'Numbers', 16, 31, 'څنګه چې د موسی خبرې خلاصې شوې، د داتان او ابیرام د پښو لاندې ځمکه سره بېله شوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_31.mp3', '', 1761754199, 1761754199),
(46099, 'Numbers 16:32', 'Numbers', 16, 32, 'او هغوی او د هغوی کورنۍ یې د قورح د ټولو پیروانو او د هغوی د مالونو سره ژوندي تېر کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_32.mp3', '', 1761754199, 1761754199),
(46100, 'Numbers 16:33', 'Numbers', 16, 33, 'نو هغوی د خپلو مالونو سره ژوندي په ځمکه ننوتل. ځمکه بېرته په هغوی باندې بنده شوه او هغوی له سترګو څخه پناه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_33.mp3', '', 1761754199, 1761754199),
(46101, 'Numbers 16:34', 'Numbers', 16, 34, 'کله چې د اسراییلو ټولو خلکو چې په هغه ځای کې وو د هغوی فریادونه واورېدل، نو وتښتېدل. هغوی چیغې ووهلې: «تښتئ، کېدای شي چې ځمکه مونږ هم ژوندي تېر کړي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_34.mp3', '', 1761754199, 1761754199),
(46102, 'Numbers 16:35', 'Numbers', 16, 35, 'بیا څښتن اور نازل کړ او هغه دوه سوه پنځوس کسان یې چې څښتن ته یې خوشبویي وړاندې کړې وه، وسوځول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_35.mp3', '', 1761754199, 1761754199),
(46103, 'Numbers 16:36', 'Numbers', 16, 36, 'بیا څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_36.mp3', '', 1761754199, 1761754199),
(46104, 'Numbers 16:37', 'Numbers', 16, 37, '«د هارون زوی العازار ته ووایه چې د سوځېدل شویو خلکو څخه د اور لوښي لېرې کړي او سکاره دې په یو لېرې ځای کې وشیندي. دا لوښي سپېڅلي دي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_37.mp3', '', 1761754199, 1761754199),
(46105, 'Numbers 16:38', 'Numbers', 16, 38, 'ځکه چې ماته د خوشبویۍ د وړاندې کولو دپاره ورڅخه کار اخیستل شوی ؤ. هغه په چا باندې په څټک وټکوه چې د قربانۍ د ځای دپاره نری پوښ ورڅخه جوړ شي. هغه خلک د خپلې ګناه له امله مړه شول او اوس به د هغوی د اور لوښي د پاتې خلکو دپاره یو خبرداری وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_38.mp3', '', 1761754199, 1761754199),
(46106, 'Numbers 16:41', 'Numbers', 16, 41, 'په راتلونکې ورځ د اسراییلو قوم د موسی او هارون په خلاف شکایت وکړ او ویې ویل: «تاسو د څښتن خلک ووژل!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_41.mp3', '', 1761754199, 1761754199),
(46107, 'Numbers 16:42', 'Numbers', 16, 42, 'کله چې هغوی ټول راټول شول چې د موسی او هارون په ضد اعتراض وکړي، موسی او هارون د سپېڅلې خېمې په لور مخ واړاوه او ویې لیدل چې خېمه ناڅاپه په ورېځ کې پټه شوه او د څښتن جلال ښکاره شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_42.mp3', '', 1761754199, 1761754199),
(46108, 'Numbers 16:43', 'Numbers', 16, 43, 'نو موسی او هارون د خېمې مخې ته ورغلل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_43.mp3', '', 1761754199, 1761754199),
(46109, 'Numbers 16:44', 'Numbers', 16, 44, 'او هلته څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_44.mp3', '', 1761754199, 1761754199),
(46110, 'Numbers 16:45', 'Numbers', 16, 45, '«شاته شئ! زه دا اسراییلیان دلته ځای په ځای له منځه وړم.» هغوی دواړو د څښتن په وړاندې پړمخې پرېوتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_45.mp3', '', 1761754199, 1761754199);